  echobeach: { name: 'Echo Beach', region: 'Bali, Indonesia', blurb: 'Left and right peaks over a rock shelf north of Canggu, punchy at size.', lat: -8.654, lon: 115.128, offshoreDeg: 60 },
  batukaras: { name: 'Batu Karas', region: 'West Java, Indonesia', blurb: 'Mellow sand-bottom right point, the gentlest good wave in Java.', lat: -7.744, lon: 108.495, offshoreDeg: 20 },
