  grumari: { name: 'Grumari', region: 'Rio de Janeiro, Brazil', blurb: 'Protected sand at the western end of Rio, backed by rainforest and rarely built on.', lat: -23.0480, lon: -43.5300, offshoreDeg: 20 },
