  pipabr: { name: 'Praia da Pipa', region: 'Rio Grande do Norte, Brazil', blurb: 'Warm-water beach and point below red cliffs, small and playful far more often than it is big.', lat: -6.2300, lon: -35.0460, offshoreDeg: 290 },
