  brimsness: { name: 'Brims Ness', region: 'Caithness, Scotland', blurb: 'Three slabs breaking over flat rock west of Thurso — short, violent, and extremely shallow.', lat: 58.6150, lon: -3.6580, offshoreDeg: 170 },
