  scarista: { name: 'Scarista', region: 'Isle of Harris, Scotland', blurb: 'Pale sand and turquoise water facing the open Atlantic, with banks that shift through the winter.', lat: 57.8350, lon: -7.0330, offshoreDeg: 80 },
